/*
 * CHIP-8 machine, Wii edition.
 *
 * Implements the machine API declared in cpu/chip8/chip8.h
 * (chip8_machine_create / _run / _destroy), like upstream GEMU's
 * hardware/machine/chip8/machine_chip8.c, but on the Wii backends instead
 * of the SDL/GTK display layer and the monitor.  The CPU core and the Octo
 * assembler are GEMU's, unchanged.
 */
#include "chip8.h"
#include "octo.h"
#include "gemu/wii.h"
#include "gemu/menubar_wii.h"
#include "gemu/video_wii.h"
#include "gemu/input_wii.h"
#include "gemu/audio_wii.h"
#include "demo_8o.h"           /* generated by bin2s from data/machine/chip8/demo.8o */

#include <gccore.h>
#include <ogc/lwp_watchdog.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>

#define MAX_8O_SOURCE (1u << 20)
#define MAX_CATCHUP   4          /* 60 Hz frames run per vblank at most */

/* Same font, same address as upstream machine_chip8.c. */
static const uint8_t chip8_font[CHIP8_FONT_BYTES] = {
    0xF0, 0x90, 0x90, 0x90, 0xF0, 0x20, 0x60, 0x20, 0x20, 0x70,
    0xF0, 0x10, 0xF0, 0x80, 0xF0, 0xF0, 0x10, 0xF0, 0x10, 0xF0,
    0x90, 0x90, 0xF0, 0x10, 0x10, 0xF0, 0x80, 0xF0, 0x10, 0xF0,
    0xF0, 0x80, 0xF0, 0x90, 0xF0, 0xF0, 0x10, 0x20, 0x40, 0x40,
    0xF0, 0x90, 0xF0, 0x90, 0xF0, 0xF0, 0x90, 0xF0, 0x10, 0xF0,
    0xF0, 0x90, 0xF0, 0x90, 0x90, 0xE0, 0x90, 0xE0, 0x90, 0xE0,
    0xF0, 0x80, 0x80, 0x80, 0xF0, 0xE0, 0x90, 0x90, 0x90, 0xE0,
    0xF0, 0x80, 0xF0, 0x80, 0xF0, 0xF0, 0x80, 0xF0, 0x80, 0x80,
};

/* Hex keypad as printed on the COSMAC VIP, row-major. */
static const uint8_t keypad_layout[16] = {
    0x1, 0x2, 0x3, 0xC,
    0x4, 0x5, 0x6, 0xD,
    0x7, 0x8, 0x9, 0xE,
    0xA, 0x0, 0xB, 0xF,
};

/* Direct controller -> keypad mapping (sideways Wii Remote / GC pad). */
static const struct { uint32_t btn; uint8_t key; } direct_map[] = {
    { WII_BTN_UP,     0x2 }, { WII_BTN_DOWN, 0x8 },
    { WII_BTN_LEFT,   0x4 }, { WII_BTN_RIGHT, 0x6 },
    { WII_BTN_ACCEPT, 0x5 }, { WII_BTN_BACK, 0x0 },
    { WII_BTN_X,      0xF }, { WII_BTN_Y,    0xE },
};

/* Chip8State comes first, so the API's Chip8State * is also a Chip8Wii *. */
typedef struct {
    Chip8State s;
    uint8_t    image[CHIP8_MEM_SIZE];   /* memory after load, for reset */
    int        cpf;                     /* instructions per 60 Hz frame */
    bool       keypad_focus;            /* D-pad drives the on-screen keypad */
    int        cursor;                  /* keypad cell, 0..15 */
    uint16_t   held;                    /* keypad state, for drawing */
    bool       paused_view;             /* Machine > Pause is on */
} Chip8Wii;

/* ── ROM loading (raw .ch8 or Octo .8o, like upstream) ───────────────────── */

static bool has_ext(const char *p, const char *ext)
{
    size_t n = strlen(p), e = strlen(ext);
    return n >= e && strcasecmp(p + n - e, ext) == 0;
}

static char *read_file(const char *path, size_t max, size_t *len)
{
    FILE *fp = fopen(path, "rb");
    if (!fp) { wii_set_error("Cannot open file"); return NULL; }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    rewind(fp);
    if (sz <= 0) { fclose(fp); wii_set_error("File is empty"); return NULL; }
    if ((size_t)sz > max) {
        fclose(fp);
        wii_set_error("File too large (%ld bytes, max %u)", sz, (unsigned)max);
        return NULL;
    }
    char *buf = malloc((size_t)sz + 1);
    if (!buf) { fclose(fp); wii_set_error("Out of memory"); return NULL; }
    if (fread(buf, 1, (size_t)sz, fp) != (size_t)sz) {
        free(buf); fclose(fp); wii_set_error("Read error"); return NULL;
    }
    fclose(fp);
    buf[sz] = '\0';
    *len = (size_t)sz;
    return buf;
}

static bool load_image(Chip8Wii *m, const char *path)
{
    uint8_t *rom = m->image + CHIP8_ROM_BASE;
    const int rom_max = CHIP8_MEM_SIZE - CHIP8_ROM_BASE;

    memset(m->image, 0, sizeof(m->image));
    memcpy(m->image + CHIP8_FONT_BASE, chip8_font, CHIP8_FONT_BYTES);

    if (!path || has_ext(path, ".8o")) {
        char *src;
        size_t len = 0;
        if (path) {
            src = read_file(path, MAX_8O_SOURCE, &len);
        } else {                                  /* built-in demo */
            src = malloc(demo_8o_size + 1);
            if (src) { memcpy(src, demo_8o, demo_8o_size); src[demo_8o_size] = '\0'; }
            else wii_set_error("Out of memory");
        }
        if (!src) return false;
        char err[256] = {0};
        int n = octo_compile(src, rom, rom_max, err, sizeof(err));
        free(src);
        if (n < 0) { wii_set_error("Octo: %s", err); return false; }
        return true;
    }

    size_t len = 0;
    char *bin = read_file(path, (size_t)rom_max, &len);
    if (!bin) return false;
    memcpy(rom, bin, len);
    free(bin);
    return true;
}

static void chip8_machine_reset(Chip8Wii *m)
{
    Chip8State *s = &m->s;
    gemu_tb_cache_flush(&s->tb_cache);
    memset(s, 0, sizeof(*s));
    gemu_tb_cache_init(&s->tb_cache, free);
    memcpy(s->mem, m->image, sizeof(s->mem));
    s->PC = CHIP8_ROM_BASE;
    s->draw_flag = true;
}

Chip8State *chip8_machine_create(const Chip8Config *cfg)
{
    Chip8Wii *m = calloc(1, sizeof(*m));
    if (!m) { wii_set_error("Out of memory"); return NULL; }
    gemu_tb_cache_init(&m->s.tb_cache, free);

    if (!load_image(m, cfg->rom_path)) {
        free(m);
        return NULL;
    }
    m->cpf    = cfg->cpu_hz;      /* cycles per frame, as upstream */
    m->cursor = 5;                /* the "5" key */
    chip8_machine_reset(m);
    return &m->s;
}

void chip8_machine_destroy(Chip8State *s)
{
    if (!s) return;
    gemu_tb_cache_flush(&s->tb_cache);
    free((Chip8Wii *)s);
}

/* ── One 60 Hz frame (mirrors upstream's display loop) ───────────────────── */

static void chip8_frame(Chip8Wii *m, uint16_t held, uint16_t pressed)
{
    Chip8State *s = &m->s;

    memcpy(s->keys_prev, s->keys, CHIP8_NUM_KEYS);
    for (int k = 0; k < CHIP8_NUM_KEYS; k++)
        s->keys[k] = (held >> k) & 1;

    if (s->wait_key && pressed) {        /* LD Vx, K */
        s->V[s->wait_reg] = (uint8_t)__builtin_ctz(pressed);
        s->wait_key = false;
        s->PC += 2;
    }

    int budget = m->cpf;
    while (budget > 0 && !s->wait_key) {
        GemuTb *tb = gemu_tb_lookup(&s->tb_cache, s->PC);
        if (!tb) tb = chip8_translate_block(s, s->PC);
        if (!tb) break;
        chip8_execute_tb(s, tb);
        budget -= (int)tb->n_insns;
    }

    /* Timers keep counting while the program waits for a key. */
    if (s->delay > 0) s->delay--;
    if (s->sound > 0) s->sound--;
}

/* ── Drawing ─────────────────────────────────────────────────────────────── */

#define KEY_CELL   40            /* keypad cell, pixels */
#define KEYPAD_W   (KEY_CELL * 4)
#define MARGIN     24              /* outer margin (TV overscan) */
#define GAP        16              /* between screen and keypad */

static void draw_keypad(const Chip8Wii *m, int x, int y)
{
    if (m->keypad_focus)                  /* focused: accent frame + cursor */
        wii_video_frame(x - 4, y - 4, KEYPAD_W + 8, KEYPAD_W + 8, 2, WII_COL_ACCENT);
    for (int i = 0; i < 16; i++) {
        int cx = x + (i % 4) * KEY_CELL, cy = y + (i / 4) * KEY_CELL;
        uint8_t key = keypad_layout[i];
        bool down = (m->held >> key) & 1;
        wii_video_fill(cx + 2, cy + 2, KEY_CELL - 4, KEY_CELL - 4,
                       down ? WII_COL_KEY_HELD : WII_COL_KEY);
        if (m->keypad_focus && i == m->cursor)
            wii_video_frame(cx, cy, KEY_CELL, KEY_CELL, 2, WII_COL_WHITE);
        char label[2] = { "0123456789ABCDEF"[key], 0 };
        wii_video_text(cx + (KEY_CELL - 16) / 2, cy + (KEY_CELL - 16) / 2, 2,
                       down ? WII_COL_BLACK : m->keypad_focus ? WII_COL_WHITE : WII_COL_GREY,
                       label);
    }
}

/*
 * Layout: the CHIP-8 screen on top, the hex keypad always visible and
 * centred below it, button hints either side of the keypad.
 */
static void draw_game(void *ud)
{
    const Chip8Wii *m = ud;
    const int W = wii_video_width(), H = wii_video_height();
    wii_video_clear(WII_COL_BLACK);

    int scale = (W - 2 * MARGIN) / CHIP8_DISPLAY_W;
    int fit_h = (H - 2 * MARGIN - GAP - KEYPAD_W) / CHIP8_DISPLAY_H;
    if (fit_h < scale) scale = fit_h;
    const int sw = CHIP8_DISPLAY_W * scale, sh = CHIP8_DISPLAY_H * scale;
    const int block_h = sh + GAP + KEYPAD_W;            /* centre the whole block */
    const int gx = (W - sw) / 2, gy = (H - block_h) / 2;
    const int kx = (W - KEYPAD_W) / 2, ky = gy + sh + GAP;

    wii_video_frame(gx - 4, gy - 4, sw + 8, sh + 8, 2, WII_COL_DARK);
    wii_video_blit_mono(m->s.vram, CHIP8_DISPLAY_W, CHIP8_DISPLAY_H,
                        gx, gy, scale, WII_COL_GAME_FG, WII_COL_GAME_BG);
    draw_keypad(m, kx, ky);

    /* Hints: left of the keypad, right-aligned; right of it, left-aligned. */
    const int lx = kx - 16, rx = kx + KEYPAD_W + 16;
    const char *left[]  = { "HOME", "Menu", m->paused_view ? "PAUSED" : NULL };
    const char *right[] = { "-/+", m->keypad_focus ? "Unfocus" : "Focus",
                            m->keypad_focus ? "2:Press" : NULL };
    for (int i = 0; i < 3; i++) {
        int y = ky + 8 + i * 24;
        uint8_t c = i == 0 ? WII_COL_WHITE : i == 2 && left[i] ? WII_COL_ACCENT : WII_COL_GREY;
        if (left[i])
            wii_video_text(lx - wii_video_text_width(2, left[i]), y, 2, c, left[i]);
        if (right[i])
            wii_video_text(rx, y, 2, i == 0 ? WII_COL_WHITE : WII_COL_GREY, right[i]);
    }
#ifdef GEMU_WII_AUTOTEST
    wii_video_textf(gx, ky + KEYPAD_W - 16, 1, WII_COL_GREY, "PC=%03X V0=%02X V1=%02X",
                    m->s.PC, m->s.V[0], m->s.V[1]);
    wii_video_textf(gx, ky + KEYPAD_W - 6, 1, WII_COL_GREY, "V2=%02X V3=%02X",
                    m->s.V[2], m->s.V[3]);
#endif
}

/* ── Menu bar items: Machine > Speed, Input > Keypad focus ─────────────── */

static const int speed_choices[] = { 5, 10, 15, 20, 30, 40, 60, 100, 200, 500, 1000 };

static bool speed_is(void *ud, int cpf)    { return ((Chip8Wii *)ud)->cpf == cpf; }
static void speed_set(void *ud, int cpf)   { ((Chip8Wii *)ud)->cpf = cpf; }
static bool keypad_focused(void *ud, int arg) { (void)arg; return ((Chip8Wii *)ud)->keypad_focus; }
static void keypad_toggle(void *ud, int arg)
{
    (void)arg;
    Chip8Wii *m = ud;
    m->keypad_focus = !m->keypad_focus;
}
static void menu_reset(void *ud) { chip8_machine_reset(ud); }

static void machine_items(void *ud, GemuMenu *machine)
{
    Chip8Wii *m = ud;
    GemuMenu *speed = gemu_menu_add_submenu(machine, "Speed");
    bool listed = false;
    for (size_t i = 0; i < sizeof(speed_choices) / sizeof(speed_choices[0]); i++) {
        char label[32];
        snprintf(label, sizeof(label), "%d ins/frame", speed_choices[i]);
        GemuMenuItem *it = gemu_menu_add(speed, GEMU_MENU_RADIO, label, speed_set, m,
                                         speed_choices[i]);
        it->checked = speed_is;
        listed |= speed_choices[i] == m->cpf;
    }
    if (!listed) {                      /* a non-standard default stays selectable */
        char label[32];
        snprintf(label, sizeof(label), "%d ins/frame", m->cpf);
        GemuMenuItem *it = gemu_menu_add(speed, GEMU_MENU_RADIO, label, speed_set, m, m->cpf);
        it->checked = speed_is;
    }
}

static void input_items(void *ud, GemuMenu *input)
{
    GemuMenuItem *it = gemu_menu_add(input, GEMU_MENU_CHECK, "Focus keypad",
                                     keypad_toggle, ud, 0);
    it->checked = keypad_focused;
    snprintf(it->shortcut, sizeof(it->shortcut), "-/+");
}

/* ── Run loop ────────────────────────────────────────────────────────────── */

static uint16_t keys_from_input(Chip8Wii *m, const WiiInput *in, uint16_t *pressed)
{
    const uint32_t cursor_btns = WII_BTN_UP | WII_BTN_DOWN | WII_BTN_LEFT |
                                 WII_BTN_RIGHT | WII_BTN_ACCEPT;
    uint16_t held = 0, down = 0;
    for (size_t i = 0; i < sizeof(direct_map) / sizeof(direct_map[0]); i++) {
        uint32_t b = direct_map[i].btn;
        if (m->keypad_focus && (b & cursor_btns))
            continue;   /* D-pad drives the cursor, ACCEPT presses the cell */
        if (in->held & b)    held |= 1u << direct_map[i].key;
        if (in->pressed & b) down |= 1u << direct_map[i].key;
    }
    if (m->keypad_focus) {
        if (in->repeat & WII_BTN_UP)    m->cursor = (m->cursor + 12) % 16;
        if (in->repeat & WII_BTN_DOWN)  m->cursor = (m->cursor + 4) % 16;
        if (in->repeat & WII_BTN_LEFT)  m->cursor = (m->cursor & ~3) | ((m->cursor + 3) & 3);
        if (in->repeat & WII_BTN_RIGHT) m->cursor = (m->cursor & ~3) | ((m->cursor + 1) & 3);
        uint16_t bit = 1u << keypad_layout[m->cursor];
        if (in->held & WII_BTN_ACCEPT)    held |= bit;
        if (in->pressed & WII_BTN_ACCEPT) down |= bit;
    }
    *pressed = down;
    return held;
}

void chip8_machine_run(Chip8State *s, const Chip8Config *cfg)
{
    Chip8Wii *m = (Chip8Wii *)s;
    wii_video_set_color(WII_COL_GAME_FG, cfg->fg_argb & 0xFFFFFF);
    wii_video_set_color(WII_COL_GAME_BG, cfg->bg_argb & 0xFFFFFF);

    WiiMenubar *menubar = wii_menubar_new(&(WiiMenubarHooks){
        .reset = menu_reset, .machine_items = machine_items,
        .input_items = input_items, .draw_frame = draw_game, .ud = m,
    });

    u64 t0 = gettime();
    u64 frames = 0;
    uint16_t pending = 0;    /* key-down edges not yet seen by the CPU */

    for (;;) {
        WiiInput in = wii_input_poll(true);
        WiiExit sys = wii_system_exit_requested();
        if (sys != WII_EXIT_NONE) { wii_request_exit(sys); break; }

        if (in.pressed & WII_BTN_PAUSE) {       /* HOME: menu bar */
            m->held = 0;
            WiiExit leave = wii_menubar_open(menubar);
            if (leave != WII_EXIT_NONE) { wii_request_exit(leave); break; }
            t0 = gettime(); frames = 0;          /* don't catch up the menu */
            continue;
        }
        if (in.pressed & WII_BTN_KEYPAD) m->keypad_focus = !m->keypad_focus;

        uint16_t pressed;
        m->held = keys_from_input(m, &in, &pressed);
        pending |= pressed;

        /* Pace CHIP-8 at 60 Hz regardless of 50/60 Hz video. */
        u64 due = ticks_to_microsecs(diff_ticks(t0, gettime())) * CHIP8_TIMER_HZ / 1000000;
        if (due - frames > MAX_CATCHUP) frames = due - MAX_CATCHUP;
        if (wii_menubar_paused(menubar)) frames = due;   /* Machine > Pause */
#ifdef GEMU_WII_AUTOTEST
        if (wii_autotest_frozen()) frames = due;
#endif
        while (frames < due) {
            chip8_frame(m, m->held, pending);
            pending = 0;                         /* edge counts once */
            frames++;
        }
        wii_audio_beep(m->s.sound > 0 && !wii_menubar_paused(menubar));

        m->paused_view = wii_menubar_paused(menubar);
        draw_game(m);
        wii_video_present();
    }
    wii_audio_beep(false);
    wii_menubar_free(menubar);
}
